+.inspector-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
+.inspector-frame-card { min-width: 0; padding: 0; overflow: hidden; border: 1px solid var(--line); border-radius: var(--r-md); background: var(--surface); color: var(--text); font: 11px/1.3 ui-monospace, SFMono-Regular, Consolas, monospace; cursor: pointer; }
+.inspector-frame-card canvas { display: block; width: 100%; height: auto; }
+.inspector-frame-card span { display: block; padding: 5px; }
+.inspector-detail { height: 100%; min-height: 0; display: flex; flex-direction: column; align-items: center; gap: 8px; }
+.inspector-detail > strong { font: 12px/1.3 ui-monospace, SFMono-Regular, Consolas, monospace; }
+.inspector-large-canvas { display: block; min-height: 0; max-width: 100%; max-height: calc(100% - 96px); width: auto; height: auto; object-fit: contain; border: 1px solid var(--line); border-radius: var(--r-md); background: #000; }
+.inspector-difference-canvas { max-height: calc(100% - 126px); }
+.inspector-hint { font-size: 11px; text-align: center; }
+.inspector-state-buttons { width: 100%; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 4px; }
+.inspector-state-buttons button { min-width: 0; padding: 0 2px; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 9px; }
+
 .settings-screen { padding-top: 4px; }
 .settings-back { align-self: flex-start; }
 .settings-card, .confirm-card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-lg); padding: 20px; }
